raw:
{
  "spells": [
    {
      "id": "spell_summon_13",
      "theory": "元素护卫术把树脂碾碎后与魔力一同压入地面浅坑，坑底纹路会把这份魔力牵向邻近的元素界域，换来一名中阶护卫短暂停留。护卫的形貌随当地元素而定，河谷多为泥石之形，城市多为风尘之形。其强度受契约条款与施术者能力双重限制，不能超越事先谈妥的职责范围。护卫只服从约定内容，不会自行扩大守护对象。",
      "casting": "单膝跪地，用树脂碎末在脚边画出闭合圈，双掌按圈心送入魔力，同时低声念出守护对象与时限。待圈内浮起细尘即算成功。",
      "failure": "圈纹若被风吹散，地面只会涌起一团松散尘土，随后归于平静，树脂与魔力俱废。若契约词句含糊，召来的形体可能反复涨缩，无法稳定成形，最终在原地塌散，留下难以清理的黏渣。",
      "counters": [
        "在圈纹完全闭合前踢散树脂碎末，召唤便无法启动。",
        "用厚布覆盖圈心，隔断魔力与地面的接触，可使其迟迟不成形。",
        "以清水冲淡树脂黏性，纹路失去附着力，护卫形体随之溃散。"
      ],
      "socialConsequences": "河谷乡约视其为正当的看护手段，牧人愿意凑树脂请人守夜。中陆公会要求施术前报备守护对象，以免护卫误拦商队。琥珀海岸的搬运工欢迎它看守货堆，但船主担心护卫在甲板上与船员争执。竞争者常以更低价钱承接同类守护，却因契约含糊而屡屡失手，反倒替熟练者做了口碑。",
      "law": {
        "river": "public",
        "city": "public",
        "port": "public"
      },
      "proficiencyEffects": [
        "低熟练度时护卫成形缓慢，常有半边虚影。",
        "熟练后圈纹一次闭合，护卫能立即站定。",
        "更熟练者可微调守护范围，减少误拦路人。",
        "高熟练度下护卫形体稳定，仍只守约定对象。"
      ]
    },
    {
      "id": "spell_summon_14",
      "theory": "界门邀约术以树脂为引，在空地上勾出一扇虚掩的门形，向邻近界域发出礼节性的来访邀请。门形本身不强行拉人，只把邀约与条款一并递出，对方可以拒绝，也可以回递条件。条款须在邀约中写明停留时限与活动范围，含糊的措辞会被对方直接搁置。术法维持期间，门形只是通话与议价的通道，不是通行的门户。",
      "casting": "用树脂在平整地面涂出两竖一横的门框，掌心贴住横梁送入魔力，逐条念出邀约条款。门框内泛起薄雾即表示邀约已递出。",
      "failure": "若树脂涂得太薄，门框会先干裂再褪色，邀约半途中断，对方只收到残缺条款，可能回递含混的答复。若条款自相矛盾，门内薄雾会凝成乱流，把双方话语搅成杂音，术者须重新勾画门框才能再次递出邀约。",
      "counters": [
        "在门框横梁上压一块湿布，薄雾便无法稳定成形。",
        "用脚抹去门框一角，邀约通道立即中断。",
        "在近旁点燃气味浓烈的树脂，干扰对方辨认条款内容。"
      ],
      "socialConsequences": "河谷乡约见证下，村民常以此邀请邻地帮手过河相助，条款谈妥后双方都安心。中陆公会要求邀约条款留档，防止有人借来访之名行刺探之实。琥珀海岸港务则关注停留时限，担心来访者滞留码头影响装卸。同行竞争者会抢先递出更宽厚的条款拉拢对方，熟练者则凭条款清晰、履约可靠而更受信任。",
      "law": {
        "river": "public",
        "city": "public",
        "port": "public"
      },
      "proficiencyEffects": [
        "低熟练度时门框薄雾稀薄，条款易被听漏。",
        "熟练后门框一次成形，邀约递出顺畅。",
        "更熟练者可清晰复述条款，减少对方误解。",
        "高熟练度下门框稳定，仍须对方自愿回应。"
      ]
    }
  ]
}
